import java.util.*;

class Solution {
    public int minStamina(int[][] cave) {
        int rows = cave.length, cols = cave[0].length;
        int[] need = new int[cols + 1];             // need[c] for the row below (and a sentinel)
        Arrays.fill(need, Integer.MAX_VALUE);
        need[cols - 1] = 1;                          // pretend we need 1 after leaving the exit
        for (int r = rows - 1; r >= 0; r--) {
            for (int c = cols - 1; c >= 0; c--) {
                int next = Math.min(need[c], need[c + 1]);   // below (old need[c]) or right
                need[c] = Math.max(1, next - cave[r][c]);    // stamina needed on entering (r, c)
            }
            need[cols] = Integer.MAX_VALUE;
        }
        return need[0];
    }
}

