class Solution:
    def minStamina(self, cave: List[List[int]]) -> int:
        R, C = len(cave), len(cave[0])
        need = [inf] * (C + 1); need[C - 1] = 1
        for r in range(R - 1, -1, -1):
            nxt = [inf] * (C + 1)
            for c in range(C - 1, -1, -1):
                nxt[c] = max(1, min(need[c], nxt[c + 1]) - cave[r][c])
            need = nxt
        return need[0]

