function minStamina(cave) {
  const R_ = cave.length, C = cave[0].length;
  const d = Array.from({ length: R_ + 1 }, () => new Array(C + 1).fill(Infinity));
  d[R_][C - 1] = 1; d[R_ - 1][C] = 1;
  for (let r = R_ - 1; r >= 0; r--) for (let c = C - 1; c >= 0; c--) d[r][c] = Math.max(1, Math.min(d[r + 1][c], d[r][c + 1]) - cave[r][c]);
  return d[0][0];
}
